sys_script_include.script:
var MSS_Equities_UpdateTask_Utils = Class.create();
MSS_Equities_UpdateTask_Utils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getStatesAndOutcomes: function() {
		var taskIDs = this.getParameter('sysparm_taskIds'); //get the passed array of task sys_ids
		var taskIDsArray = taskIDs.split(",");
        var returnedObj;
		var outcomesArrayInit = [];
		var stateArray = [];
		var actualStateArray = [];
        var taskNumberArray = [];

		var grTask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
        grTask.addQuery('sys_id', 'IN', taskIDsArray);
        grTask.query();

        while (grTask.next()) {
			var taskShortDesc = grTask.getValue('short_description');
            var taskNumber = grTask.getValue('number');
            var state = grTask.getDisplayValue('state');
			actualStateArray.push(state);

			taskNumberArray.push(taskNumber);

			var taskTemplate = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task_template');
			taskTemplate.addQuery('short_description', taskShortDesc);
			taskTemplate.query();
			if (taskTemplate.next()) {
				var taskTemplateOutcome = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task_outcome_mapping');
				taskTemplateOutcome.addQuery('trade_template', taskTemplate.sys_id);
				taskTemplateOutcome.query();
				var outcomesArrayOneTask = [];
				while(taskTemplateOutcome.next()) {
					var automatedTaskChoice;
                    automatedTaskChoice = taskTemplateOutcome.getValue('outcome'); // store outcome value
					if (!outcomesArrayOneTask.includes(automatedTaskChoice)) {  //Avoid to add duplicated elements
                        outcomesArrayOneTask.push(automatedTaskChoice);
					}
				}
				outcomesArrayInit.push(outcomesArrayOneTask);
			} else {
				outcomesArrayInit.push([]);
			}
		}

        // Find common elements across all arrays for outcome
        var outcomesArrayFinal = outcomesArrayInit.reduce(function(accumulator, currentArray) {
            return accumulator.filter(function(element) {
                return currentArray.includes(element);
            });
        }, outcomesArrayInit[0]); // Start with the first array as the initial accumulator

        if (actualStateArray.includes('Closed Complete') || actualStateArray.includes('Closed Rejected') || actualStateArray.includes('Cancelled')) {

		} else {
			stateArray.push({name:'New',value:1});
		    stateArray.push({name:'Work in Progress',value:2});
		    stateArray.push({name:'Closed Complete',value:3});
		    stateArray.push({name:'Closed Rejected',value:4});
		    stateArray.push({name:'Awaiting Info',value:6});
            stateArray.push({name:'Cancelled',value:7});
		    stateArray.push({name:'Reviewed',value:8});
		}
		returnedObj = {
            outcomesArray: outcomesArrayFinal,
            stateArray: stateArray,
			taskNumberArray: taskNumberArray
        };

        return JSON.stringify(returnedObj);
    },

    updateSelectedTasks: function() {
        var taskIDs = this.getParameter('sysparm_taskIds'); //get the passed array of task sys_ids
		var outcome = this.getParameter('sysparm_outcome');
        var state = this.getParameter('sysparm_state');
        var worknotes = this.getParameter('sysparm_worknotes');

        var taskIDsArray = taskIDs.split(",");

        var grTask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
        grTask.addQuery('sys_id', 'IN', taskIDsArray);
        grTask.query();

        while (grTask.next()) {
			grTask.outcome = outcome;
            grTask.state = state;
            grTask.work_notes = worknotes;
			grTask.update();
		}

		return true;
    },

    // To ensure the UI Action "UpdateSelected" is only available in the "Tasks assigned to me" list view
	checkAvailabilityOfUpdateSelected: function() {
		var filter = gs.action.getGlideURI().get('sysparm_query');
        var result = false;

		if (filter) {
			// "Task assigned to me" view - Check and ensure only "assigned to me" in filter with AND operator and without any other "assigned to" conditions
            if (filter.includes('assigned_toDYNAMIC90d1921e5f510100a9ad2572f2b477fe') && !filter.match(/assigned_to(?!DYNAMIC90d1921e5f510100a9ad2572f2b477fe)/g) && !filter.includes('^ORassigned_toDYNAMIC90d1921e5f510100a9ad2572f2b477fe')) {
			    if (gs.hasRole("mss_user") || gs.hasRole("mss_manager")) {
				    result = true;
			    } else {
				    result = false;
			    }
		    } else if (filter.includes('assignment_groupDYNAMICd6435e965f510100a9ad2572f2b47744') && !filter.includes('^ORassignment_groupDYNAMICd6435e965f510100a9ad2572f2b47744')) {  // "Task assigned to my group" view - Check and ensure "assigned to my group" in filter with AND operator
                if (gs.hasRole("mss_manager")) {
				    result = true;
			    } else {
				    result = false;
			    }
			} else {
			    result = false;
		    }
		} else {
			result = false;
		}

		return result;
	},

    type: 'MSS_Equities_UpdateTask_Utils'
});
